import { DataWidget } from './DataWidget.js';
import { icon } from './icons.js';
export class ScheduleWidget extends DataWidget {
  constructor(config,dashboard){super({...config,title:'Расписание дня'},dashboard);this.editing=false;}
  update(){const date=this.store.selectedDate;const events=this.store.data.schedule.filter(s=>s.date===date).sort((a,b)=>a.time.localeCompare(b.time));const dateRow=this.element('div','widget-subheading');const input=this.input('selected','День расписания','date',date);input.className='date-control';dateRow.append(input,this.actionButton(this.editing?'Скрыть':'＋ Событие','edit'));const list=this.element('div','schedule-list');events.forEach(item=>{const row=this.element('div',`schedule-row${item.done?' finished':''}`);const time=this.element('span','schedule-time',item.time);const badge=this.element('span',`schedule-icon category-${item.category==='Творчество'?0:item.category==='Развитие'?1:2}`);badge.append(icon(item.category==='Творчество'?'projects':item.category==='Развитие'?'note':'habits'));const text=this.element('div','schedule-text');text.append(this.element('strong','',item.text),this.element('small','',`${item.category} · ${item.duration} мин`));const check=this.actionButton(item.done?'✓':'○','toggle',`${item.done?'Отменить отметку':'Завершить'}: ${item.text}`);check.dataset.id=item.id;check.className='event-check';check.setAttribute('aria-pressed',String(item.done));row.append(time,badge,text,check);if(this.editing){const remove=this.actionButton('×','delete',`Удалить событие: ${item.text}`);remove.dataset.id=item.id;row.append(remove);}list.append(row);});if(!events.length)list.append(this.empty('Свободный день. Добавь что-нибудь важное.'));this.content.replaceChildren(dateRow,list);if(this.editing){const form=this.element('form','inline-form');const text=this.input('text','Название события');text.required=true;text.maxLength=160;const time=this.input('time','Время','time','10:00');time.required=true;const duration=this.input('duration','Минуты','number','30');duration.min=5;duration.max=240;form.append(text,time,duration,this.select('category','Категория',[['Творчество','Творчество'],['Развитие','Развитие'],['Личное','Личное']]),this.submitButton('Добавить'));this.content.append(form);} }
  action(action,button){if(action==='edit'){this.editing=!this.editing;this.update();if(this.editing)this.content.querySelector('[name=text]').focus();}if(action==='toggle')this.store.toggleEvent(button.dataset.id);if(action==='delete')this.store.deleteEvent(button.dataset.id);}
  change(event){if(event.target.name==='selected')this.store.selectDate(event.target.value);}
  submit(form,values){this.store.addEvent({text:values.get('text'),time:values.get('time'),duration:Number(values.get('duration')),category:values.get('category'),date:this.store.selectedDate});this.content.querySelector('[name=text]')?.focus();}
}
